return ['domain'=>'blocksocial-license-server','plural-forms'=>'nplurals=2; plural=n > 1;','language'=>'fr_FR','project-id-version'=>'BlockSocial Lizenzserver 1.0.0','pot-creation-date'=>'2026-10-19T20:13:58+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['BlockSocial Lizenzserver'=>'BlockSocial Serveur de licences','https://blocksocial.eu'=>'https://blocksocial.eu','Verkauf und Verwaltung von Plugin-Lizenzen über WooCommerce: Lizenzschlüssel beim Kauf, Plätze (verbundene Shops) je Lizenzstufe, Verlängerung und Upgrade im Kundenkonto, automatische Plugin-Updates für Lizenznehmer.'=>'Vente et gestion de licences d’extensions via WooCommerce : clé de licence à l’achat, emplacements (boutiques connectées) par niveau de licence, renouvellement et mise à niveau depuis le compte client, mises à jour automatiques de l’extension pour les titulaires de licence.','BlockSocial UG (haftungsbeschränkt)'=>'BlockSocial UG (haftungsbeschränkt)','BlockSocial Lizenzserver benötigt WooCommerce.'=>'BlockSocial Serveur de licences nécessite WooCommerce.','Lizenzen'=>'Licences','Hauptshop freigegeben. Du kannst die Lizenz jetzt in einem anderen Hauptshop aktivieren.'=>'Boutique principale libérée. Vous pouvez maintenant activer la licence sur une autre boutique principale.','Du hast noch keine Lizenzen.'=>'Vous n’avez encore aucune licence.','Lizenzschlüssel'=>'Clé de licence','Stufe'=>'Niveau','Shops'=>'Boutiques','Hauptshop'=>'Boutique principale','Gültig bis'=>'Valable jusqu’au','Status'=>'État','Verwalten'=>'Gérer','Alle Lizenzen'=>'Toutes les licences','Plätze'=>'Emplacements','Updates & Support bis'=>'Mises à jour et support jusqu’au','Verlängern'=>'Renouveler','Upgrade auf %s (unbegrenzt viele Shops)'=>'Mettre à niveau vers %s (boutiques illimitées)','Upgrade auf %1$s (bis %2$d Shops)'=>'Mettre à niveau vers %1$s (jusqu’à %2$d boutiques)','Downloads'=>'Téléchargements','Downloads und Updates sind mit einer aktiven Lizenz verfügbar.'=>